package com.fertiplus.notification;import org.springframework.web.bind.annotation.*;import java.util.Map;@RestController @RequestMapping("/api/notifications")public class NotificationController{@PostMapping public Map<String,Object> send(@RequestBody Map<String,Object> body){return Map.of("status","ACCEPTED","message","Demo notification accepted; configure an SMS/email provider for real delivery","payload",body);}@GetMapping("/health")public Map<String,String> health(){return Map.of("status","UP");}}
